import unittest

from solucao import so_letra
from solucao import so_numero


class TestSoNumerosOuSoLetras(unittest.TestCase):
    def test_numero_com_espacos_nas_pontas(self):
        """so_numero ignora os espacos das pontas e devolve True"""
        self.assertEqual(so_numero("  123  "), True)

    def test_numero_com_letra(self):
        """so_numero devolve False quando tem letra no meio"""
        self.assertEqual(so_numero("12a"), False)

    def test_letra_com_espacos_nas_pontas(self):
        """so_letra ignora os espacos das pontas e devolve True"""
        self.assertEqual(so_letra(" ana "), True)

    def test_espaco_no_meio_nao_vale(self):
        """so_letra devolve False quando o espaco esta no meio do texto"""
        self.assertEqual(so_letra("an a"), False)

